#!/usr/bin/env python3"""Тест для проверки добавления чатов в папки с авторизацией"""import requestsimport jsonimport timedef test_add_chat_to_folder_with_auth():    """Тестировать добавление чата в папку с авторизацией"""    base_url = "http://localhost:8000"        print("🧪 Тестируем добавление чата в папку с авторизацией...")        try:        # Сначала проверим, что сервер работает        print("🔍 Проверяем доступность сервера...")        response = requests.get(f"{base_url}/api", timeout=5)        if response.status_code != 200:            print(f"❌ Сервер недоступен: {response.status_code}")            return False        print("✅ Сервер доступен")                # Создаем тестового пользователя        print("\n👤 Создаем тестового пользователя...")        user_data = {            "username": "test_user_folders",            "email": "test_folders@example.com",            "password": "testpassword123"        }                # Попробуем зарегистрировать пользователя        response = requests.post(f"{base_url}/auth/register", json=user_data, timeout=5)        if response.status_code == 201:            print("✅ Пользователь создан")        elif response.status_code == 400:            print("⚠️ Пользователь уже существует")        else:            print(f"⚠️ Неожиданный статус регистрации: {response.status_code}")            print(f"Ответ: {response.text}")                # Авторизуемся        print("\n🔐 Авторизуемся...")        login_data = {            "username": user_data["username"],            "password": user_data["password"]        }                response = requests.post(f"{base_url}/auth/login-json", json=login_data, timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка авторизации: {response.status_code}")            print(f"Ответ: {response.text}")            return False                auth_data = response.json()        token = auth_data.get("access_token")        if not token:            print("❌ Токен не получен")            return False                print("✅ Авторизация успешна")                # Создаем папку        print("\n📁 Создаем тестовую папку...")        folder_data = {            "name": "Тестовая папка для чатов",            "description": "Папка для тестирования добавления чатов",            "folder_type": "custom",            "icon": "folder",            "color": "bg-blue-500",            "chat_ids": [],            "agent_ids": []        }                headers = {"Authorization": f"Bearer {token}"}        response = requests.post(f"{base_url}/folders/", json=folder_data, headers=headers, timeout=5)        if response.status_code not in [200, 201]:            print(f"❌ Ошибка создания папки: {response.status_code}")            print(f"Ответ: {response.text}")            return False                folder = response.json()        folder_id = folder["id"]        print(f"✅ Папка создана с ID: {folder_id}")                # Получаем список агентов        print("\n🤖 Получаем список агентов...")        response = requests.get(f"{base_url}/agents/", headers=headers, timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка получения агентов: {response.status_code}")            return False                agents = response.json()        if not agents:            print("❌ Агенты не найдены")            return False                agent = agents[0]        agent_id = agent["id"]        print(f"✅ Найден агент: {agent['name']} (ID: {agent_id})")                # Создаем чат        print("\n💬 Создаем тестовый чат...")        chat_data = {            "agent_id": agent_id        }                response = requests.post(f"{base_url}/chat/new", json=chat_data, headers=headers, timeout=5)        if response.status_code not in [200, 201]:            print(f"❌ Ошибка создания чата: {response.status_code}")            print(f"Ответ: {response.text}")            return False                chat = response.json()        chat_id = chat["id"]        print(f"✅ Чат создан с ID: {chat_id}")                # Добавляем чат в папку        print(f"\n➕ Добавляем чат {chat_id} в папку {folder_id}...")        response = requests.post(f"{base_url}/folders/{folder_id}/chats/{chat_id}", headers=headers, timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка добавления чата в папку: {response.status_code}")            print(f"Ответ: {response.text}")            return False                print("✅ Чат успешно добавлен в папку")                # Проверяем, что чат действительно добавлен        print("\n🔍 Проверяем содержимое папки...")        response = requests.get(f"{base_url}/folders/{folder_id}", headers=headers, timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка получения папки: {response.status_code}")            return False                updated_folder = response.json()        chat_ids = updated_folder.get("chat_ids", [])                # Если chat_ids - строка, парсим её как JSON        if isinstance(chat_ids, str):            try:                chat_ids = json.loads(chat_ids)            except:                chat_ids = []                if chat_id in chat_ids:            print("✅ Чат найден в папке")        else:            print("❌ Чат не найден в папке")            print(f"ID чатов в папке: {chat_ids}")            return False                # Удаляем чат из папки        print(f"\n➖ Удаляем чат {chat_id} из папки {folder_id}...")        response = requests.delete(f"{base_url}/folders/{folder_id}/chats/{chat_id}", headers=headers, timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка удаления чата из папки: {response.status_code}")            print(f"Ответ: {response.text}")            return False                print("✅ Чат успешно удален из папки")                # Проверяем, что чат удален        print("\n🔍 Проверяем, что чат удален из папки...")        response = requests.get(f"{base_url}/folders/{folder_id}", headers=headers, timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка получения папки: {response.status_code}")            return False                updated_folder = response.json()        chat_ids = updated_folder.get("chat_ids", [])                # Если chat_ids - строка, парсим её как JSON        if isinstance(chat_ids, str):            try:                chat_ids = json.loads(chat_ids)            except:                chat_ids = []                if chat_id not in chat_ids:            print("✅ Чат успешно удален из папки")        else:            print("❌ Чат все еще в папке")            print(f"ID чатов в папке: {chat_ids}")            return False                print("\n🎉 Все тесты прошли успешно!")        return True            except Exception as e:        print(f"❌ Ошибка при тестировании: {e}")        import traceback        traceback.print_exc()        return Falseif __name__ == "__main__":    print("🚀 Тест добавления чатов в папки с авторизацией")    print("=" * 60)        if test_add_chat_to_folder_with_auth():        print("✅ Все тесты прошли успешно!")    else:        print("❌ Тесты не прошли")